  pub(crate) fn process_state_test_lock() -> ProcessStateTestGuard {
      let lock = PROCESS_STATE_TEST_LOCK
          .lock()
          .unwrap_or_else(|error| error.into_inner());
      ProcessStateTestGuard {
          original_dir: std::env::current_dir().ok(),
          _lock: lock,
      }
  }
