   4	/// Serialize unit tests that observe or mutate process-global state such as
   5	/// the current directory or environment variables.
   6	static PROCESS_STATE_TEST_LOCK: Mutex<()> = Mutex::new(());
   7	
   8	/// Holds the process-state lock and puts the current directory back where it
   9	/// was once the guard drops.
  10	///
  11	/// A test that moves into a directory and then panics never reaches its own
  12	/// restore line. The guard restores the directory for it: otherwise the next
  13	/// `std::env::current_dir()` in the binary goes through libc's `getcwd`
  14	/// fallback, which climbs `..` and reads each parent directory to recover the
  15	/// name; under a `$TMPDIR` full of test scratch that costs seconds per call,
  16	/// and the rest of the run crawls. The mutation lane saw this as a mutant the
  17	/// key tests do observe scoring TIMEOUT instead of caught, because the failing
  18	/// test was one of the two that change directory.
  19	pub(crate) struct ProcessStateTestGuard {
  20	    original_dir: Option<PathBuf>,
  21	    _lock: MutexGuard<'static, ()>,
  22	}
  23	
  24	impl ProcessStateTestGuard {
  25	    /// Make a fresh [`cwd_dir`] the current directory until the guard drops.
  26	    pub(crate) fn enter(&mut self) -> PathBuf {
  27	        let path = cwd_dir();
  28	        std::env::set_current_dir(&path).unwrap();
  29	        path
  30	    }
  31	}
  32	
  33	impl Drop for ProcessStateTestGuard {
  34	    fn drop(&mut self) {
  35	        // Runs before the lock field drops, so the directory is back before
  36	        // the next test can take the lock. Best effort: a panic here while
  37	        // already unwinding would abort the whole test binary.
  38	        if let Some(dir) = self.original_dir.take() {
  39	            let _ = std::env::set_current_dir(dir);
  40	        }
  41	    }
  42	}
  43	
  44	/// Directories tests made the current directory, kept until the binary exits.
  45	///
  46	/// A child process inherits the current directory when it starts. A test that
  47	/// spawns rustc without the lock can therefore start it inside another test's
  48	/// directory, and rustc can still be starting when that test finishes. rustc
  49	/// panics when its working directory no longer exists ("expecting a current
  50	/// working directory to exist"), so deleting the directory at the end of the
  51	/// test failed unrelated dep-info tests at random.
  52	static CWD_DIRS: Mutex<Vec<tempfile::TempDir>> = Mutex::new(Vec::new());
  53	
  54	/// A new directory a test may make the current directory. It stays on disk
  55	/// until the test binary exits; see [`CWD_DIRS`].
  56	pub(crate) fn cwd_dir() -> PathBuf {
  57	    static REMOVE_AT_EXIT: std::sync::Once = std::sync::Once::new();
  58	    REMOVE_AT_EXIT.call_once(|| {
  59	        // SAFETY: registers a plain function that captures nothing. Exiting
  60	        // runs it after the harness has joined every test, so no child a test
  61	        // spawned is still running.
  62	        unsafe { libc::atexit(remove_cwd_dirs) };
  63	    });
  64	    let dir = tempfile::tempdir().unwrap();
  65	    let path = dir.path().to_path_buf();
  66	    CWD_DIRS
  67	        .lock()
  68	        .unwrap_or_else(|error| error.into_inner())
  69	        .push(dir);
  70	    path
  71	}
  72	
  73	extern "C" fn remove_cwd_dirs() {
  74	    // Unwinding out of an `extern "C"` function aborts, so skip a poisoned
  75	    // lock rather than unwrap it.
  76	    if let Ok(mut dirs) = CWD_DIRS.lock() {
  77	        dirs.clear();
  78	    }
  79	}
