  81	/// Keep a poisoned lock usable so one failing test does not cascade into
  82	/// unrelated failures.
  83	pub(crate) fn process_state_test_lock() -> ProcessStateTestGuard {
  84	    let lock = PROCESS_STATE_TEST_LOCK
  85	        .lock()
  86	        .unwrap_or_else(|error| error.into_inner());
  87	    ProcessStateTestGuard {
  88	        original_dir: std::env::current_dir().ok(),
  89	        _lock: lock,
  90	    }
  91	}
