 144	/// kunobi-ninja/kache#1205: Ctrl-C in the terminal signals the whole
 145	/// foreground process group, and an auto-started daemon used to be part of
 146	/// it. A caller in its own group starts a stand-in daemon through the real
 147	/// spawn path; interrupting that group must leave the daemon running, with
 148	/// the arguments, environment and stderr the daemon is meant to get.
 149	#[cfg(unix)]
 150	#[test]
 151	fn detached_daemon_survives_sigint_to_the_callers_group() {
 152	    use std::os::unix::fs::PermissionsExt;
 153	    use std::os::unix::process::CommandExt;
 154	
 155	    let dir = tempfile::tempdir().unwrap();
 156	    let root = dir.path();
 157	    let script = root.join("kache");
 158	    std::fs::write(
 159	        &script,
 160	        format!(
 161	            "#!/bin/sh\nprintf '%s\\n' \"$@\" > '{0}/args'\nenv > '{0}/env'\n\
 162	                 echo daemon-stderr >&2\ntouch '{0}/ready'\nexec sleep 30\n",
 163	            root.display()
 164	        ),
 165	    )
 166	    .unwrap();
 167	    std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o755)).unwrap();
 168	
 169	    let mut caller = std::process::Command::new(std::env::current_exe().unwrap())
 170	        .args([
 171	            "--exact",
 172	            "daemon::tests::detached_daemon_caller_fixture",
 173	            "--ignored",
 174	            "--nocapture",
 175	        ])
 176	        .env(DETACH_FIXTURE_DIR, root)
 177	        .process_group(0)
 178	        .spawn()
 179	        .unwrap();
 180	    // The caller is a second copy of this debug test binary; on a loaded
 181	    // machine its start alone can take seconds.
 182	    let deadline = std::time::Instant::now() + Duration::from_secs(30);
 183	    while !(root.join("pid").exists() && root.join("ready").exists()) {
 184	        assert!(
 185	            caller.try_wait().unwrap().is_none(),
 186	            "the caller exited before starting the daemon"
 187	        );
 188	        assert!(
 189	            std::time::Instant::now() < deadline,
 190	            "the daemon never started"
 191	        );
 192	        std::thread::sleep(Duration::from_millis(20));
 193	    }
 194	    let daemon: i32 = std::fs::read_to_string(root.join("pid"))
 195	        .unwrap()
 196	        .parse()
 197	        .unwrap();
 198	    let caller_group = caller.id() as i32;
 199	
 200	    assert_eq!(unsafe { libc::kill(-caller_group, libc::SIGINT) }, 0);
 201	    let status = caller.wait().unwrap();
 202	    // Give a daemon that shared the group time to die, then look.
 203	    std::thread::sleep(Duration::from_millis(300));
 204	    let survived = unsafe { libc::kill(daemon, 0) } == 0;
 205	    let session = unsafe { libc::getsid(daemon) };
 206	    unsafe { libc::kill(daemon, libc::SIGKILL) };
 207	
 208	    assert!(!status.success(), "SIGINT never reached the caller's group");
 209	    assert!(survived, "the daemon died with its caller's process group");
 210	    assert_eq!(session, daemon, "the daemon must lead its own session");
 211	
 212	    let args = std::fs::read_to_string(root.join("args")).unwrap();
 213	    assert_eq!(args, "daemon\nrun\n");
 214	    let env = std::fs::read_to_string(root.join("env")).unwrap();
 215	    let marker = format!("{}=", crate::platform::SELF_SPAWN_ENV);
 216	    assert!(
 217	        env.lines().any(|line| line.starts_with(&marker)),
 218	        "the daemon must be marked as a self-spawn: {env}"
 219	    );
 220	    for name in AMBIENT_REMOTE_ENV_VARS {
 221	        let prefix = format!("{name}=");
 222	        assert!(
 223	            !env.lines().any(|line| line.starts_with(&prefix)),
 224	            "{name} leaked into the daemon's environment"
 225	        );
 226	    }
 227	    let log = std::fs::read_to_string(root.join("daemon.log")).unwrap();
 228	    assert_eq!(log, "daemon-stderr\n", "stderr must go to the daemon log");
 229	}
